Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<algorithm>
#include<cstdio>
#include<queue>
#define Maxn 5500
#define Maxm 35500
#define INF 1000000000
using namespace std;
struct Line
{int nxt,t,c,l;}g[Maxm];
int fir[Maxn],tl=1;
void adl(int f,int t,int c,int cost){
  g[++tl]=(Line){fir[f],t,c,cost};fir[f]=tl;
  g[++tl]=(Line){fir[t],f,0,-cost};fir[t]=tl;
}
int S,T,pre[Maxn],lp[Maxn],flow[Maxn],dis[Maxn];
bool in[Maxn];
queue<int> q;
int spfa()
{
  for (int i=1;i<=T;i++)
    {dis[i]=INF;flow[i]=0;}
  flow[S]=INF;dis[S]=0;
  q.push(S);in[S]=1;
  while(!q.empty()){
    int u=q.front();
    in[u]=0;q.pop();
    for (int i=fir[u],v;i;i=g[i].nxt)
      if (g[i].c&&dis[v=g[i].t]>dis[u]+g[i].l){
        dis[v]=dis[u]+g[i].l;
        flow[v]=min(flow[u],g[i].c);
        lp[v]=i;pre[v]=u;
        if (!in[v]){in[v]=1;q.push(v);}
     }
  }return flow[T];
}
int n,m,k,C,D,pl[105][105],st[105][105];
struct Data
{int f,t;}s[105];
#define P(x,y) ((x)*n+(y))
int main()
{
  scanf("%d%d%d%d%d",&n,&m,&k,&C,&D);
  S=P(n+k,n)+1;T=S+2;
  adl(P(0,1),T,INF,0);
  for (int i=1,p;i<=k;i++){
    scanf("%d",&p);
    adl(S,P(0,p),1,0);
  }for (int i=1;i<=m;i++){
    scanf("%d%d",&s[i*2].f,&s[i*2].t);
    s[i*2-1]=(Data){s[i*2].t,s[i*2].f};
  }m*=2;
  for (int t=1;t<=n+k;t++){
    for (int i=1;i<=n;i++)
      adl(P(t-1,i),P(t,i),INF,0);
    for (int i=1;i<=m;i++){
      adl(P(t-1,s[i].f),P(t,s[i].t),1,D);
      pl[t][i]=tl;st[t][i]=1;
    }adl(P(t,1),T,INF,t*C);
  }
  int sav,cans=0;
  while(sav=spfa()){
    int u=T;
    while(u!=S){
      int las=pre[u];
      g[lp[u]].c-=sav;
      g[lp[u]^1].c+=sav;
      u=las;
    }cans+=dis[T]*sav;
    for (int t=1;t<=n+n;t++)
      for (int i=1;i<=m;i++)
        if (g[pl[t][i]].c){
          st[t][i]++;
          adl(P(t-1,s[i].f),P(t,s[i].t),1,D*(st[t][i]*2-1));
          pl[t][i]=tl;
        }
  }printf("%d\n",cans);
  return 0;
}
